<template><div class="page"><div class="page-head"><div><h1 class="page-title">读者管理</h1><div class="page-sub">管理读者档案、借阅额度和信用状态</div></div><el-button type="primary" @click="open()"><el-icon><Plus/></el-icon>新增读者</el-button></div><div class="toolbar"><el-input v-model="keyword" placeholder="读者编号或姓名" style="width:300px" clearable/><el-button type="primary" plain @click="load">查询</el-button></div><el-card class="table-card"><el-table :data="rows"><el-table-column prop="readerNo" label="读者编号"/><el-table-column prop="realName" label="姓名"/><el-table-column prop="college" label="学院"/><el-table-column prop="major" label="专业"/><el-table-column prop="readerType" label="类型"><template #default="{row}"><el-tag>{{row.readerType==='STUDENT'?'学生':'教师'}}</el-tag></template></el-table-column><el-table-column prop="maxBorrowCount" label="借阅上限"/><el-table-column label="信用分"><template #default="{row}"><span :style="{color:row.creditScore>=80?'#23946f':'#e06464',fontWeight:700}">{{row.creditScore}}</span></template></el-table-column><el-table-column label="状态"><template #default><el-tag type="success">正常</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination background layout="total,prev,pager,next" :total="total" v-model:current-page="page" @current-change="load"/></div></el-card><el-dialog v-model="visible" title="读者档案" width="560"><el-form label-position="top"><div class="grid"><el-form-item label="关联用户ID"><el-input-number v-model="form.userId"/></el-form-item><el-form-item label="读者编号"><el-input v-model="form.readerNo"/></el-form-item><el-form-item label="读者类型"><el-select v-model="form.readerType"><el-option label="学生" value="STUDENT"/><el-option label="教师" value="TEACHER"/></el-select></el-form-item><el-form-item label="学院"><el-input v-model="form.college"/></el-form-item><el-form-item label="专业"><el-input v-model="form.major"/></el-form-item><el-form-item label="最大借阅数"><el-input-number v-model="form.maxBorrowCount"/></el-form-item></div></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template><script setup lang="ts">import{ref,reactive,onMounted}from'vue';import api from'../api';import{ElMessage}from'element-plus';const rows=ref<any[]>([]),total=ref(0),page=ref(1),keyword=ref(''),visible=ref(false),form=reactive<any>({});onMounted(load);async function load(){const r:any=await api.get('/api/readers',{params:{page:page.value,size:10,keyword:keyword.value}});rows.value=r.records;total.value=r.total}function open(r:any={}){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,r,{readerType:r.readerType||'STUDENT',maxBorrowCount:r.maxBorrowCount||5});visible.value=true}async function save(){form.id?await api.put(`/api/readers/${form.id}`,form):await api.post('/api/readers',form);ElMessage.success('保存成功');visible.value=false;load()}</script><style scoped>.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}</style>

